import { HonestCompare } from "march/landing"
import { Segmented } from "march/ui"

// kedi mi köpek mi: tarafını seç, tablo kendi tarafını dürüstçe puanlar (nerede geride olduğunu da söyler)
const ROWS = [
  { label: "Sabah yürüyüşü ister", values: { kedi: false, kopek: true } },
  { label: "Evde yalnız kalabilir", values: { kedi: true, kopek: "partial" as const } },
  { label: "Kapıda karşılar", values: { kedi: "partial" as const, kopek: true } },
  { label: "Kum kabı ister", values: { kedi: true, kopek: false } },
]

type Counts = { ahead: number; even: number; behind: number }

export function CatOrDog() {
  let $side: "kedi" | "kopek" = "kedi"
  return <div sx={{ flex: "col", gap: 3 }}>
    <Segmented aria-label="Tarafın" options={[{ value: "kedi", label: "🐱 Kedi" }, { value: "kopek", label: "🐶 Köpek" }]} bind:value={$side} />
    {() => { const side = $side; return <HonestCompare us={side} caption="Kedi ve köpek" columns={[{ id: "kedi", name: "🐱 Kedi" }, { id: "kopek", name: "🐶 Köpek" }]} rows={ROWS}
      labels={{ counts: (c: Counts) => `${c.ahead} konuda önde, ${c.behind} konuda geride` }} /> }}
  </div>
}

import { HonestCompare } from "march/landing"

// bir not uygulamasının fiyat sayfasındaki dürüst karşılaştırma: geride kaldığı satırlarda nedenini ve planı yazar
export function NotesAppCompare() {
  return <section sx={{ flex: "col", gap: 3 }}>
    <h2>Defter ve diğerleri: dürüst bir karşılaştırma</h2>
    <HonestCompare showCaption caption="Defter, Büyük Not ve Kâğıt"
      columns={[{ id: "us", name: "Defter" }, { id: "big", name: "Büyük Not" }, { id: "paper", name: "Kâğıt defter" }]}
      rows={[
        { label: "Çevrimdışı çalışır", values: { us: true, big: "partial", paper: true } },
        { label: "Uçtan uca şifreleme", values: { us: true, big: false, paper: "partial" } },
        { label: "El yazısı tanıma", values: { us: false, big: true, paper: false }, note: "Henüz yok. İlkbahar sürümünde geliyor; şimdilik fotoğraf eklenebiliyor." },
        { label: "Ekip paylaşımı", values: { us: "partial", big: true, paper: false }, note: "Beş kişiye kadar ortak defter. Daha büyük ekipler için Büyük Not daha uygun." },
        { label: "Aylık fiyat", values: { us: "49 ₺", big: "129 ₺", paper: "Bir kez 60 ₺" } },
      ]} />
  </section>
}

import { test, expect, renderTest } from "march/testing"
import { HonestCompareLab } from "./HonestCompareLab.tsx"

// HonestCompareLab'in testleri: kaydedince Testler sekmesinde çalışır
test("özet kendi sayım metniyle; başlık ve bölge adı", () => {
  const s = renderTest(() => <HonestCompareLab />)
  expect(s.get(".lab-hc .m-hc-counts")?.textContent).toBe("2 önde · 0 eşit · 2 geride")
  expect(s.get(".lab-hc caption")?.textContent).toBe("İşe nasıl gidelim?")
  expect(s.find("Ulaşım tablosu")).not.toBe(null)
})

test("geride kalan satırlar etiketli; süzgeç yalnız onları bırakır", async () => {
  const s = renderTest(() => <HonestCompareLab />)
  expect(s.all(".lab-hc .m-hc-tag.is-behind").length).toBe(2)
  await s.click("Yalnız geride olduklarımız")
  expect(s.all(".lab-hc tr.m-hc-row.is-hidden").length).toBe(3)
  expect(s.find("Hepsini göster")).not.toBe(null)
})

test("etiketler kapanınca gider", async () => {
  const s = renderTest(() => <HonestCompareLab />)
  await s.click("Etiketler")
  expect(s.container.querySelector(".lab-hc .m-hc-tag")).toBe(null)
})

test("kendi hücre çizimi: Var / Yok, kendi sütunumuz işaretli", async () => {
  const s = renderTest(() => <HonestCompareLab />)
  await s.click("Yazıyla hücreler")
  expect(s.all(".lab-hc b.lab-mine").length).toBe(3)
  expect(s.get(".lab-hc b.lab-mine")?.textContent).toBe("Var")
})
